"""Reusable conversions for Meridian CRM 4.2 storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP, localcontext


_LEGACY_NULL_DATE = "00000000"
_DEFAULT_CURRENCY = "USD"


def _require_ascii_digits(value: str, length: int, label: str) -> None:
    if len(value) != length or any(char < "0" or char > "9" for char in value):
        raise ValueError(f"{label} must contain exactly {length} ASCII digits")


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == _LEGACY_NULL_DATE:
        return None

    _require_ascii_digits(yyyymmdd, 8, "legacy date")
    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso is None or iso == "":
        return _LEGACY_NULL_DATE

    if (
        len(iso) != 10
        or iso[4] != "-"
        or iso[7] != "-"
    ):
        raise ValueError("ISO date must have the form YYYY-MM-DD")

    digits = iso[0:4] + iso[5:7] + iso[8:10]
    _require_ascii_digits(digits, 8, "ISO date")

    parsed = date(
        int(iso[0:4]),
        int(iso[5:7]),
        int(iso[8:10]),
    )
    return f"{parsed.year:04d}{parsed.month:02d}{parsed.day:02d}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag, treating blank as N."""
    if char == "Y":
        return True
    if char in ("N", "", None):
        return False
    raise ValueError("legacy boolean must be 'Y', 'N', blank, or None")


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units, half-up."""
    if amount is None or amount == "":
        decimal_amount = Decimal(0)
    else:
        decimal_amount = Decimal(str(amount))

    effective_currency = _DEFAULT_CURRENCY if currency in (None, "") else currency
    exponent = 0 if effective_currency == "JPY" else 2
    scale = Decimal(10) ** exponent

    if not decimal_amount.is_finite():
        raise ValueError("amount must be finite")

    decimal_tuple = decimal_amount.as_tuple()
    precision = max(
        50,
        len(decimal_tuple.digits) + max(decimal_tuple.exponent, 0) + exponent + 10,
    )

    with localcontext() as context:
        context.prec = precision
        rounded = (decimal_amount * scale).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )

    return int(rounded)
